"""Prometheus metrics — custom counters, gauges, histogram."""

from prometheus_client import Counter, Gauge, Histogram

# ---- HTTP metrics are auto-generated by Instrumentator ----

# ---- WebSocket ----
ws_connections_active = Gauge(
    "raqib_ws_connections_active",
    "Number of currently active WebSocket connections",
)

ws_messages_sent_total = Counter(
    "raqib_ws_messages_sent_total",
    "Total number of WebSocket messages broadcast",
)

ws_auth_failures_total = Counter(
    "raqib_ws_auth_failures_total",
    "WebSocket handshakes rejected due to invalid/missing token",
)

# ---- Insights ----
insights_requests_total = Counter(
    "raqib_insights_requests_total",
    "Total /api/insights requests",
)

runbook_generated_total = Counter(
    "raqib_runbook_generated_total",
    "Total runbooks generated, partitioned by severity",
    labelnames=("severity",),
)

# ---- Auth ----
auth_attempts_total = Counter(
    "raqib_auth_attempts_total",
    "Authentication attempts",
    labelnames=("endpoint", "result"),
)

# ---- Latency (business-level) ----
insights_duration_seconds = Histogram(
    "raqib_insights_duration_seconds",
    "Latency of /api/insights handler",
    buckets=(0.001, 0.005, 0.01, 0.05, 0.1, 0.5, 1.0),
)
